        var comparison=Parse(ChangeReports.Compare(snapshot.ToJsonString(),snapshot.ToJsonString(),Int(profile["MaxAgeHours"]),now));
        var result=ExplainTool(profile,tool,inventory,snapshot,comparison,prerequisites,now);result["InputSha256"]=new JsonObject{["Profile"]=Hash(profile),["Requirements"]=Hash(requirements),["Inventory"]=Hash(inventory),["Snapshot"]=Hash(snapshot),["Prerequisites"]=Hash(prerequisites)};return result.ToJsonString();
    });
